NUMD_HELP = [
    "# numdeep - الحساب العددي والعلمي العميق: مصفوفات وجبر خطي وإحصاء وتكامل (numpy / scipy)",
]

_NUMD_TOKEN = re.compile(
    r"(?P<dot>\.)?"
    r"(?P<word>(?!\d)[\w\u064B-\u065F\u0670]+)"
    r"(?P<open>\s*\()?"
)

USER_NAMES = set()


def _numdeep_replace(match):
    dot = match.group("dot")
    word = match.group("word")
    open_paren = match.group("open")
    if word in USER_NAMES:
        return match.group(0)
    if dot:
        return match.group(0)
    if word in NUMD_CONSTS:
        return NUMD_CONSTS[word]
    if word in NUMD_FUNCS:
        return NUMD_FUNCS[word] + (open_paren or "")
    return match.group(0)


def NUMD_SUBSTITUTE(text):
    """يترجم كلمات المكتبة في نص واحد ويُرجع المترجم."""
    if not text:
        return text
    return _NUMD_TOKEN.sub(_numdeep_replace, text)
